using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;

namespace Lumora.Audio;

// RNNoise's LITTLE model plus the DSP tables, read once from an embedded resource and shared by
// every denoiser.
//
// Resource layout, little-endian (written by model/convert_model.c):
//   header, 16 bytes: "RNNL", uint32 format version, uint32 record count, uint32 file length
//   record, 4-byte aligned: uint8 name length, uint8 type (1 float32, 2 int32, 3 int8, 4 ASCII),
//     uint16 zero, uint32 element count, name padded to 4 bytes, elements padded to 4 bytes
// Arrays keep RNNoise's own layouts; the record set must match the one below exactly.
internal sealed class RnnoiseModel
{
    internal const string ResourceName = "Lumora.Audio.Denoise.rnnoise-little.bin";

    private const uint FormatVersion = 1;
    private const byte TypeFloat32 = 1;
    private const byte TypeInt32 = 2;
    private const byte TypeInt8 = 3;
    private const byte TypeText = 4;

    private const int FeatureCount = 65;
    private const int Conv1Out = 128;
    private const int Conv2Out = 384;
    private const int GruSize = 384;
    private const int DenseIn = Conv2Out + 3 * GruSize;

    private static readonly Lazy<RnnoiseModel> _shared = new(LoadEmbedded, LazyThreadSafetyMode.ExecutionAndPublication);

    internal static RnnoiseModel Shared => _shared.Value;

    internal readonly string Version;
    internal readonly FloatLinearLayer Conv1;
    internal readonly Int8LinearLayer Conv2;
    internal readonly Int8LinearLayer Gru1Input;
    internal readonly Int8LinearLayer Gru1Recurrent;
    internal readonly Int8LinearLayer Gru2Input;
    internal readonly Int8LinearLayer Gru2Recurrent;
    internal readonly Int8LinearLayer Gru3Input;
    internal readonly Int8LinearLayer Gru3Recurrent;
    internal readonly FloatLinearLayer DenseOut;
    internal readonly FloatLinearLayer VadDense;
    internal readonly float[] HalfWindow;
    internal readonly float[] DctTable;
    internal readonly KissFft Fft;

    private RnnoiseModel(Records r)
    {
        Version = r.Text("model_version");
        Conv1 = new FloatLinearLayer(r.Floats("conv1_weights_float", 3 * FeatureCount * Conv1Out), r.Floats("conv1_bias", Conv1Out), 3 * FeatureCount, Conv1Out);
        Conv2 = Int8LinearLayer.Dense(r.Bytes("conv2_weights_int8", 3 * Conv1Out * Conv2Out), r.Floats("conv2_scale", Conv2Out), r.Floats("conv2_subias", Conv2Out), 3 * Conv1Out, Conv2Out);
        Gru1Input = Gru(r, "gru1_input", false);
        Gru1Recurrent = Gru(r, "gru1_recurrent", true);
        Gru2Input = Gru(r, "gru2_input", false);
        Gru2Recurrent = Gru(r, "gru2_recurrent", true);
        Gru3Input = Gru(r, "gru3_input", false);
        Gru3Recurrent = Gru(r, "gru3_recurrent", true);
        DenseOut = new FloatLinearLayer(r.Floats("dense_out_weights_float", DenseIn * 32), r.Floats("dense_out_bias", 32), DenseIn, 32);
        VadDense = new FloatLinearLayer(r.Floats("vad_dense_weights_float", DenseIn), r.Floats("vad_dense_bias", 1), DenseIn, 1);
        HalfWindow = r.Floats("rnn_half_window", 480);
        DctTable = r.Floats("rnn_dct_table", 32 * 32);
        Fft = new KissFft(r.Floats("fft_twiddles", 2 * KissFft.Size), r.Ints("fft_bitrev", KissFft.Size));
        r.EnsureAllUsed();
    }

    // Both GRU matrices are block sparse; only the recurrent one keeps a float diagonal.
    private static Int8LinearLayer Gru(Records r, string name, bool recurrent)
    {
        const int outputs = 3 * GruSize;
        float[] scale = r.Floats(name + "_scale", outputs);
        float[] subias = r.Floats(name + "_subias", outputs);
        float[]? diag = recurrent ? r.Floats(name + "_weights_diag", outputs) : null;
        int[] idx = r.Ints(name + "_weights_idx", -1);
        sbyte[] weights = r.Bytes(name + "_weights_int8", -1);
        try
        {
            return Int8LinearLayer.Sparse(weights, idx, scale, subias, diag, GruSize, outputs);
        }
        catch (InvalidDataException e)
        {
            throw Records.Invalid($"{name}: {e.Message}");
        }
    }

    internal static RnnoiseModel Parse(byte[] data)
    {
        try
        {
            return new RnnoiseModel(new Records(data));
        }
        catch (InvalidDataException e) when (!e.Message.StartsWith(Records.Prefix, StringComparison.Ordinal))
        {
            throw Records.Invalid(e.Message);
        }
    }

    private static RnnoiseModel LoadEmbedded()
    {
        Assembly assembly = typeof(RnnoiseModel).Assembly;
        using Stream? stream = assembly.GetManifestResourceStream(ResourceName);
        if (stream == null)
            throw new InvalidOperationException($"RNNoise model resource '{ResourceName}' is missing from {assembly.GetName().Name}; embed rnnoise-little.bin with that LogicalName.");
        var data = new byte[stream.Length];
        stream.ReadExactly(data);
        return Parse(data);
    }

    private sealed class Records
    {
        internal const string Prefix = "RNNoise model resource is invalid: ";

        private readonly byte[] _data;
        private readonly Dictionary<string, (byte Type, int Count, int Offset)> _records = new(StringComparer.Ordinal);
        private readonly HashSet<string> _used = new(StringComparer.Ordinal);

        internal Records(byte[] data)
        {
            _data = data;
            if (data.Length < 16 || data[0] != 'R' || data[1] != 'N' || data[2] != 'N' || data[3] != 'L')
                throw Invalid("bad magic, expected \"RNNL\"");
            uint version = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(4));
            if (version != FormatVersion)
                throw Invalid($"format version {version}, this build reads version {FormatVersion}");
            uint count = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(8));
            uint length = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(12));
            if (length != data.Length)
                throw Invalid($"header says {length} bytes, resource has {data.Length}");

            int at = 16;
            for (uint i = 0; i < count; i++)
            {
                if (at + 8 > data.Length)
                    throw Invalid($"record {i} header runs past the end");
                int nameLength = data[at];
                byte type = data[at + 1];
                uint elements = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(at + 4));
                int size = type switch
                {
                    TypeFloat32 or TypeInt32 => 4,
                    TypeInt8 or TypeText => 1,
                    _ => throw Invalid($"record {i} has unknown type {type}"),
                };
                if (nameLength == 0 || at + 8 + nameLength > data.Length)
                    throw Invalid($"record {i} has a bad name length");
                string name = Encoding.ASCII.GetString(data, at + 8, nameLength);
                int offset = at + 8 + Align(nameLength);
                long end = offset + (long)elements * size;
                if (end > data.Length)
                    throw Invalid($"'{name}' runs past the end");
                if (!_records.TryAdd(name, (type, (int)elements, offset)))
                    throw Invalid($"'{name}' appears twice");
                at = offset + Align((int)(elements * (uint)size));
            }
            if (at != data.Length)
                throw Invalid($"{data.Length - at} bytes after the last record");
        }

        private static int Align(int n) => (n + 3) & ~3;

        internal static InvalidDataException Invalid(string reason) => new(Prefix + reason);

        private (int Count, int Offset) Find(string name, byte type, int count)
        {
            if (!_records.TryGetValue(name, out var r))
                throw Invalid($"missing '{name}'");
            if (r.Type != type)
                throw Invalid($"'{name}' has type {r.Type}, expected {type}");
            if (count >= 0 && r.Count != count)
                throw Invalid($"'{name}' has {r.Count} elements, expected {count}");
            _used.Add(name);
            return (r.Count, r.Offset);
        }

        // count -1 accepts any length; the layer that owns the array checks it.
        internal float[] Floats(string name, int count)
        {
            var (n, offset) = Find(name, TypeFloat32, count);
            var result = new float[n];
            ReadInto(MemoryMarshal.AsBytes(result.AsSpan()), offset);
            return result;
        }

        internal int[] Ints(string name, int count)
        {
            var (n, offset) = Find(name, TypeInt32, count);
            var result = new int[n];
            ReadInto(MemoryMarshal.AsBytes(result.AsSpan()), offset);
            return result;
        }

        internal sbyte[] Bytes(string name, int count)
        {
            var (n, offset) = Find(name, TypeInt8, count);
            var result = new sbyte[n];
            ReadInto(MemoryMarshal.AsBytes(result.AsSpan()), offset);
            return result;
        }

        internal string Text(string name)
        {
            var (n, offset) = Find(name, TypeText, -1);
            return Encoding.ASCII.GetString(_data, offset, n);
        }

        // x64 and ARM64 are little-endian, so element bytes copy across as they are.
        private void ReadInto(Span<byte> destination, int offset) => _data.AsSpan(offset, destination.Length).CopyTo(destination);

        internal void EnsureAllUsed()
        {
            foreach (string name in _records.Keys)
            {
                if (!_used.Contains(name))
                    throw Invalid($"unexpected record '{name}'");
            }
        }
    }
}
